CREATE TABLE app_user (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), demo boolean NOT NULL DEFAULT false);
CREATE TABLE auth_session (id text PRIMARY KEY, expires_at timestamp NOT NULL, token text NOT NULL UNIQUE, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE);
CREATE INDEX auth_session_user_idx ON auth_session(user_id);
CREATE TABLE auth_account (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamp, refresh_token_expires_at timestamp, scope text, password text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX auth_account_user_idx ON auth_account(user_id);
CREATE UNIQUE INDEX auth_account_provider_uq ON auth_account(provider_id, account_id);
CREATE TABLE auth_verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamp NOT NULL, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE INDEX auth_verification_identifier_idx ON auth_verification(identifier);
CREATE TABLE profiles (user_id text PRIMARY KEY REFERENCES app_user(id) ON DELETE CASCADE, locale text NOT NULL DEFAULT 'ar' CHECK(locale IN ('ar','en')), currency text NOT NULL DEFAULT 'ILS' CHECK(currency IN ('ILS','USD','EUR')), timezone text NOT NULL DEFAULT 'Asia/Jerusalem', onboarded boolean NOT NULL DEFAULT false);
CREATE TABLE financial_accounts (id text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, name text NOT NULL, type text NOT NULL CHECK(type IN ('bank','cash','wallet')), currency text NOT NULL CHECK(currency IN ('ILS','USD','EUR')), opening_balance bigint NOT NULL CHECK(abs(opening_balance) <= 1000000000000), UNIQUE(id,user_id));
CREATE INDEX financial_accounts_owner_idx ON financial_accounts(user_id);
CREATE TABLE categories (id text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, name text NOT NULL, name_ar text NOT NULL, kind text NOT NULL CHECK(kind IN ('income','expense')), color text NOT NULL, UNIQUE(id,user_id));
CREATE INDEX categories_owner_idx ON categories(user_id);
CREATE TABLE transactions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, account_id text NOT NULL, category_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('income','expense')), amount bigint NOT NULL CHECK(amount > 0 AND amount <= 1000000000000), currency text NOT NULL CHECK(currency IN ('ILS','USD','EUR')), date date NOT NULL, note text NOT NULL DEFAULT '', source_key text, FOREIGN KEY(account_id,user_id) REFERENCES financial_accounts(id,user_id), FOREIGN KEY(category_id,user_id) REFERENCES categories(id,user_id));
CREATE INDEX transactions_owner_date_idx ON transactions(user_id,date);
CREATE UNIQUE INDEX transactions_owner_source_uq ON transactions(user_id,source_key);
CREATE TABLE transfers (id text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, from_account_id text NOT NULL, to_account_id text NOT NULL, amount bigint NOT NULL CHECK(amount > 0 AND amount <= 1000000000000), date date NOT NULL, note text NOT NULL DEFAULT '', CHECK(from_account_id <> to_account_id), FOREIGN KEY(from_account_id,user_id) REFERENCES financial_accounts(id,user_id), FOREIGN KEY(to_account_id,user_id) REFERENCES financial_accounts(id,user_id));
CREATE INDEX transfers_owner_idx ON transfers(user_id);
CREATE TABLE budgets (id text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, category_id text NOT NULL, month text NOT NULL CHECK(month ~ '^\d{4}-(0[1-9]|1[0-2])$'), amount bigint NOT NULL CHECK(amount > 0 AND amount <= 1000000000000), currency text NOT NULL CHECK(currency IN ('ILS','USD','EUR')), FOREIGN KEY(category_id,user_id) REFERENCES categories(id,user_id));
CREATE UNIQUE INDEX budget_month_category_uq ON budgets(user_id,category_id,month,currency);
CREATE TABLE goals (id text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, name text NOT NULL, target bigint NOT NULL CHECK(target > 0 AND target <= 1000000000000), currency text NOT NULL CHECK(currency IN ('ILS','USD','EUR')), deadline date NOT NULL, UNIQUE(id,user_id));
CREATE INDEX goals_owner_idx ON goals(user_id);
CREATE TABLE contributions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, goal_id text NOT NULL, account_id text NOT NULL, amount bigint NOT NULL CHECK(amount > 0 AND amount <= 1000000000000), date date NOT NULL, FOREIGN KEY(goal_id,user_id) REFERENCES goals(id,user_id) ON DELETE CASCADE, FOREIGN KEY(account_id,user_id) REFERENCES financial_accounts(id,user_id));
CREATE INDEX contributions_owner_idx ON contributions(user_id);
CREATE TABLE recurring (id text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, name text NOT NULL, account_id text NOT NULL, category_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('income','expense')), amount bigint NOT NULL CHECK(amount > 0 AND amount <= 1000000000000), currency text NOT NULL CHECK(currency IN ('ILS','USD','EUR')), frequency text NOT NULL CHECK(frequency IN ('weekly','monthly','yearly')), next_date date NOT NULL, active boolean NOT NULL DEFAULT true, FOREIGN KEY(account_id,user_id) REFERENCES financial_accounts(id,user_id), FOREIGN KEY(category_id,user_id) REFERENCES categories(id,user_id));
CREATE INDEX recurring_owner_date_idx ON recurring(user_id,next_date);
CREATE TABLE notes (id text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL, created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX notes_owner_idx ON notes(user_id);
CREATE TABLE demo_sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, expires_at timestamp NOT NULL);
